package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.*;

/** New-cohort full restriction-digestion HiC2.1.0 workflow and portable scientific-contract replay. */
public final class NfcoreHic210ToolsCli {
    private NfcoreHic210ToolsCli(){ }
    static final String ACTION="Required action: require the latest wrapper COMPLETED.json and successful --verify before downstream use. Read WARNINGS.md, FAILURE.json, failure.stacktrace, original engine trace/logs and export-process diagnostics. SKIP3/exit3 skips analysis when an exact permitted prerequisite or capability is absent: complete named permitted setup separately or retain the skip. No analysis downloads or installs software. FAIL2/exit2 admits no complete result: preserve every attempt, correct the named input/hash/source/runtime/process/numerical/capacity cause and use NEW paths when the immutable request changes. Never restart a live or indeterminate run. Resume retains the same producing JAR, inputs, science, cache and original path. All selected source-default mapping, balancing, multiresolution, compartments, distance decay, requested TAD callers, QC and version-report branches must finish. Native checks cover the complete paired FASTQ cohort, source mapping/classification counts, every valid-pair ID/projection row and every selected balanced.cool bin/raw integer pixel against the complete literal FASTA. Reference labels do not certify assembly identity or select an iGenomes preset. NaN bin weights remain explicit unassessable markers; no weight/ID/coordinate is repaired. Sparse data may produce zero source TAD calls; no negative biological conclusion is inferred. Other fit outputs and mcool files remain fully captured but have no independent numerical parity contract here. Per-task MPLCONFIGDIR=.matplotlib supplies a writable cache without changing original source or scientific options. Source null/missing version tokens and all warnings remain visible. Saved verification recomputes contracts from complete captured inputs and exported arrays; it does not rerun original fits, decode HDF5 again, readmit a host or reproduce an unresolved author recipe. Hashes establish integrity, not authenticity. Capacities are checked bounds, not OS memory/disk quotas; provision resources for the entire cohort. Cell Ranger remains excluded.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try{
            if(args.length==0||args.length==1&&args[0].equals("--help")){emit(out,"nfcore-hic210-tools --request REQUEST.json --home EXACT_NEXTFLOW22_HOME --setup-report COMPLETED_SETUP --out NEW_LINUX_SESSION\nnfcore-hic210-tools --resume ORIGINAL_SESSION --home EXACT_NEXTFLOW22_HOME --setup-report COMPLETED_SETUP\nnfcore-hic210-tools --verify SAVED_SESSION\nnfcore-hic210-tools --export-image-setup NEW_DIRECTORY\nOriginal126-file source/17 Git executables,14 exact images/30 aliases; paired-end restriction-digestion cohorts, explicit FASTA/science/limits. See docs/nfcore-hic210.md.\n"+ACTION);return out.checkError()?2:0;}
            if(args.length==2&&args[0].equals("--export-image-setup")){NfcoreHic210Profile.exportSetup(Path.of(args[1]));emit(out,"Exact original image setup exported. No installation or analysis executed.\n"+ACTION);return out.checkError()?2:0;}
            if(args.length==2&&args[0].equals("--verify")){var result=NfcoreHic210Bundle.verify(Path.of(args[1]));emit(out,"Complete selected original Hi-C source-output contracts verified: "+result.attempt()+"; manifest SHA256 "+result.manifest().sha256()+".\n"+ACTION);return out.checkError()?2:0;}
            var options=new LinkedHashMap<String,String>();for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!Set.of("--request","--out","--resume","--home","--setup-report").contains(args[i])||options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require unique typed Hi-C value options; see --help");boolean resume=options.containsKey("--resume");if(resume&&(options.containsKey("--request")||options.containsKey("--out"))||!resume&&(!options.containsKey("--request")||!options.containsKey("--out")))throw new IOException("New Hi-C analysis requires --request and --out; resume uses only saved context plus exact runtime home/report");Path root=Path.of(options.get(resume?"--resume":"--out"));var attempt=NfcoreHic210Workflow.run(root,resume?null:Path.of(options.get("--request")),optional(options,"--home"),optional(options,"--setup-report"),resume);emit(out,"Complete selected original Hi-C workflow and native source-output contracts completed: "+attempt+".\n"+ACTION);return out.checkError()?2:0;
        }catch(Exception|LinkageError failure){int code=NfcoreHic210Workflow.exit(failure);emit(err,(code==3?"SKIP3 - ANALYSIS SKIPPED: ":"FAIL2 - NO RESULT ADMITTED: ")+failure+"\n"+ACTION);return code;}
    }
    private static Path optional(Map<String,String> options,String name){return options.containsKey(name)?Path.of(options.get(name)):null;}
    private static void emit(PrintStream stream,String value){stream.writeBytes((value+"\n").getBytes(StandardCharsets.UTF_8));}
}
